    if stale:
        return base - (Decimal('0.10') if size_cls == 'large' else Decimal('0.05'))
    return base

def reindex_exempt(r):
    if parse_bool(r['maintenance_active']) is not True:
        return False, 'maintenance_active not True'
    rl = reindex.get(r['table_name'])
    if not rl:
        return False, 'no reindex log entry'
    if parse_bool(rl['approved']) is not True:
        return False, f"approved={rl['approved']}"
    vu = date.fromisoformat(rl['valid_until'])
    if not (vu > AUDIT_DATE):
        return False, f"valid_until {rl['valid_until']} not > 2026-09-01"
    return True, f"reindex valid_until {rl['valid_until']} > 2026-09-01"

def qualifying_hold(table):
    t = tickets.get(table)
    if not t:
        return None, 'no ticket'
    if t['exception_type'] != 'BLOAT_HOLD':
        return None, f"exception_type {t['exception_type']}"
    if t['status'] != 'Closed':
        return None, f"status {t['status']}"
    if parse_bool(t['approved']) is not True:
        return None, f"approved={t['approved']}"
    vu = date.fromisoformat(t['valid_until'])
    if not (vu > AUDIT_DATE):
        return None, f"valid_until {t['valid_until']} not > 2026-09-01"
