    if not re.search(r'compute|computed|computing|derived from total_pages', line, re.I): issues.append((t,'compute concept missing'))
    if h['size_class'].lower()=='medium' and 'medium' not in line.lower(): issues.append((t,'medium trap label missing'))
    if finding=='AUTOVACUUM_DISABLED':
        if 'autovacuum' not in line.lower() and 'auto-vacuum' not in line.lower(): issues.append((t,'autovacuum token missing'))
        if h['vacuum_type']=='manual' and ('manual' not in line.lower() or 'vacuum' not in line.lower()): issues.append((t,'manual vacuum tokens missing'))
    if finding=='STALE_STATISTICS':
        if str(days) not in line: issues.append((t,'stale day count missing'))
        if 'stale' not in line.lower() and 'stats' not in line.lower(): issues.append((t,'stale/stats wording missing'))
        if 'days_since_analyze' not in line and 'legacy days field' not in line: issues.append((t,'legacy days_since_analyze missing'))
        if not re.search(r'tighten|tightened|reduced cap|effective cap', line, re.I): issues.append((t,'tightening wording missing'))
    if finding=='BLOAT_THRESHOLD_EXCEEDED':
        if 'round' not in line.lower(): issues.append((t,'rounding wording missing'))
        if stale and not re.search(r'tighten|tightened|reduced cap|effective cap', line, re.I): issues.append((t,'tightening wording missing'))
        if tickets.get(t):
            if tickets[t]['ticket_id'] not in line: issues.append((t,'ticket id missing'))
            if 'hold' not in line.lower() and 'ticket' not in line.lower(): issues.append((t,'hold/ticket wording missing'))
        if h['maintenance_active'].lower()=='true' and reindex.get(t):
            if 'reindex' not in line.lower() and 're-index' not in line.lower(): issues.append((t,'reindex token missing'))
            rl=reindex[t]
            if rl['approved'].lower()!='true' and not re.search(r'unapproved|not approved|approved=false', line, re.I): issues.append((t,'unapproved reindex wording missing'))
            if date.fromisoformat(rl['valid_until'])<=date(2026,9,1) and not re.search(r'expired|lapsed|no longer valid|past validity|approval ended', line, re.I): issues.append((t,'reindex expiry wording missing'))
print('issues', len(issues))
for x in issues[:100]: print(x)
print('line lengths >450')
over=[(t,line,len(line)) for t,line in lines.items() if len(line)>450]
